async function loadFinanceSummary(){const target=document.querySelector('[data-finance-summary]');if(!target)return;target.textContent='Загружаем баланс…';try{const r=await fetch('/api/finance/balance',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json(),s=data.student;target.textContent='Осталось уроков: '+s.remaining_lessons+'. Баланс: '+(s.balance_kopecks/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽.';}catch{target.textContent='Баланс временно недоступен. Откройте раздел оплат и попробуйте обновить.'}}
